const FLY_API = "https://api.machines.dev/v1";
const TOKEN = process.env.FLY_API_TOKEN!;
const APP = process.env.FLY_APP_NAME!;

async function flyFetch(path: string, opts?: RequestInit): Promise<unknown> {
  const res = await fetch(`${FLY_API}${path}`, {
    ...opts,
    headers: {
      "Content-Type": "application/json",
      Authorization: `Bearer ${TOKEN}`,
      ...opts?.headers,
    },
  });
  if (!res.ok) {
    const body = await res.text();
    throw new Error(`Fly API ${res.status}: ${body}`);
  }
  return res.status === 204 ? null : res.json();
}

export async function listMachines() {
  return flyFetch(`/apps/${APP}/machines`) as Promise<unknown[]>;
}

export async function getMachine(machineId: string) {
  return flyFetch(`/apps/${APP}/machines/${machineId}`);
}

export async function stopMachine(machineId: string) {
  return flyFetch(`/apps/${APP}/machines/${machineId}/stop`, { method: "POST" });
}

export async function startMachine(machineId: string) {
  return flyFetch(`/apps/${APP}/machines/${machineId}/start`, { method: "POST" });
}
